import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import {
  sourceApiAssociationConfigSchema,
  type SourceApiAssociationConfig,
} from "./source-api-association-config.js";

export type V1SourceApisMergedApiAssociationsRequest = {
  /**
   * The identifier of the AppSync Merged API. This is generated by the AppSync service. In most
   * cases, Merged APIs (especially in your account) only require the API ID value or ARN of the
   * merged API. However, Merged APIs in other accounts (cross-account use cases) strictly require
   * the full resource ARN of the merged API.
   */
  mergedApiIdentifier: string;
  /** The description field. */
  description?: string;
  sourceApiAssociationConfig?: SourceApiAssociationConfig;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const v1SourceApisMergedApiAssociationsRequestSchema: Schema<V1SourceApisMergedApiAssociationsRequest> =
  s.object<V1SourceApisMergedApiAssociationsRequest>(
    {
      mergedApiIdentifier: s.string(),
      description: s.optional(s.string()),
      sourceApiAssociationConfig: s.optional(s.lazy(() => sourceApiAssociationConfigSchema)),
    },
    { additionalProperties: s.json() },
  );
